/**
 * A form field: label, control (children), hint and error text. `htmlFor` ties the label to the id of the
 * control.
 */
import { type ReactNode } from "react";
import { Box, Label, Text } from "../compose";
import { cn } from "../utils";

export type FieldProps = {
  label: string;
  htmlFor: string;
  hint?: string;
  error?: string;
  className?: string;
  children?: ReactNode;
};

export function Field({ label, htmlFor, hint, error, className, children }: FieldProps) {
  return (
    <Box className={cn("flex min-w-0 flex-col gap-2", className)}>
      <Label className="text-xs font-bold text-foreground" htmlFor={htmlFor}>
        {label}
      </Label>
      {children}
      {error ? (
        <Text className="m-0 text-xs font-semibold text-destructive" role="alert">
          {error}
        </Text>
      ) : hint ? (
        <Text className="m-0 text-xs font-medium text-muted-foreground">
          {hint}
        </Text>
      ) : null}
    </Box>
  );
}
